from pathlib import Path
import subprocess, sys
p = Path("js/customer-app.js")
src = p.read_text(encoding="utf-8")
old_lines = len(src.split("\n"))
marker = "    // ═══ Auth Listener ═══"
new_block = """    window._openNotifications = function() {\n        const prefs = _getNotifPrefs();\n        function row(key, icon, title, desc, on) {\n            const bg = on ? \"#e8f5e9\" : \"#ecf0f1\";\n            const fg = on ? \"#2e7d32\" : \"#95a5a6\";\n            const label = on ? \"ON\" : \"OFF\";\n            return \"<div onclick=\\u0027_toggleNotif(\\\\\\u0027\" + key + \"\\\\\\u0027, this)\\u0027 data-key=\\\\\"\" + key + \"\\\\\" data-on=\\\\\"\" + (on ? \"1\" : \"0\") + \"\\\\\" style=\\\\\"padding:16px;border-bottom:1px solid #f0f0f0;display:flex;align-items:center;gap:12px;cursor:pointer;\\\\\">\"\n                + \"<div style=\\\\\"font-size:22px;\\\\\">\" + icon + \"</div>\"\n                + \"<div style=\\\\\"flex:1;\\\\\"><div style=\\\\\"font-size:14px;font-weight:800;color:#2c3e50;\\\\\">\" + title + \"</div>\"\n                + \"<div style=\\\\\"font-size:12px;color:#7f8c8d;margin-top:2px;\\\\\">\" + desc + \"</div></div>\"\n                + \"<div class=\\\\\"_notifSwitch\\\\\" style=\\\\\"background:\" + bg + \";color:\" + fg + \";font-size:11px;font-weight:900;padding:5px 12px;border-radius:20px;min-width:44px;text-align:center;\\\\\">\" + label + \"</div></div>\";\n        }\n        const html = \"<div id=\\\\\"_notifModal\\\\\" style=\\\\\"position:fixed;inset:0;background:rgba(0,0,0,0.55);z-index:9999;display:flex;align-items:flex-end;justify-content:center;\\\\\" onclick=\\\\\"if(event.target===this)this.remove();\\\\\">\"\n            + \"<div style=\\\\\"background:white;border-radius:24px 24px 0 0;width:100%;max-width:500px;max-height:85vh;overflow-y:auto;padding-bottom:20px;\\\\\">\"\n            + \"<div style=\\\\\"padding:20px;border-bottom:1px solid #f0f0f0;display:flex;align-items:center;justify-content:space-between;position:sticky;top:0;background:white;z-index:2;\\\\\">\"\n            + \"<div style=\\\\\"font-size:18px;font-weight:900;color:#2c3e50;\\\\\">\\ud83d\\udd14 \\u0627\\u0644\\u0625\\u0634\\u0639\\u0627\\u0631\\u0627\\u062a</div>\"\n            + \"<button onclick=\\\\\"document.getElementById(\\\\\\u0027_notifModal\\\\\\u0027).remove()\\\\\" style=\\\\\"background:#ecf0f1;border:none;width:36px;height:36px;border-radius:50%;font-size:16px;cursor:pointer;font-family:inherit;\\\\\">\\u2715</button>\"\n            + \"</div>\"\n            + \"<div>\"\n            + row(\"orders\", \"\\ud83d\\udce6\", \"\\u0625\\u0634\\u0639\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u0637\\u0644\\u0628\\u0627\\u062a\", \"\\u062a\\u062d\\u062f\\u064a\\u062b\\u0627\\u062a \\u062d\\u0627\\u0644\\u0629 \\u0637\\u0644\\u0628\\u0643\", prefs.orders)\n            + row(\"offers\", \"\\ud83c\\udf81\", \"\\u0625\\u0634\\u0639\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u0639\\u0631\\u0648\\u0636\", \"\\u062e\\u0635\\u0648\\u0645\\u0627\\u062a \\u0645\\u0646 \\u0627\\u0644\\u0645\\u062a\\u0627\\u062c\\u0631\", prefs.offers)\n            + row(\"support\", \"\\ud83d\\udcac\", \"\\u0625\\u0634\\u0639\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u062f\\u0639\\u0645\", \"\\u0631\\u062f\\u0648\\u062f \\u0627\\u0644\\u062f\\u0639\\u0645 \\u0648\\u0627\\u0644\\u0645\\u0633\\u0627\\u0639\\u062f\\u0629\", prefs.support)\n            + row(\"sound\", \"\\ud83d\\udd0a\", \"\\u0625\\u0634\\u0639\\u0627\\u0631\\u0627\\u062a \\u0635\\u0648\\u062a\\u064a\\u0629\", \"\\u062a\\u0634\\u063a\\u064a\\u0644 \\u0635\\u0648\\u062a \\u0639\\u0646\\u062f \\u0627\\u0644\\u0625\\u0634\\u0639\\u0627\\u0631\", prefs.sound)\n            + \"</div>\"\n            + \"<div style=\\\\\"padding:16px;\\\\\">\"\n            + \"<div style=\\\\\"background:#f3e5f5;border-right:4px solid #8e44ad;border-radius:10px;padding:12px 14px;font-size:12px;color:#6a1b9a;line-height:1.6;\\\\\">\"\n            + \"<b>\\u2139\\ufe0f \\u0645\\u0644\\u0627\\u062d\\u0638\\u0629:</b> \\u0627\\u0644\\u0625\\u0634\\u0639\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u0641\\u0648\\u0631\\u064a\\u0629 (Push) \\u0633\\u062a\\u064f\\u0641\\u0639\\u064e\\u0651\\u0644 \\u0639\\u0646\\u062f \\u0625\\u0637\\u0644\\u0627\\u0642 \\u0627\\u0644\\u062a\\u0637\\u0628\\u064a\\u0642 \\u0627\\u0644\\u0631\\u0633\\u0645\\u064a (APK) \\u0642\\u0631\\u064a\\u0628\\u0627\\u064b.\"\n            + \"</div></div>\"\n            + \"<div style=\\\\\"padding:0 16px 16px;\\\\\">\"\n            + \"<button onclick=\\\\\"_saveNotifPrefs()\\\\\" style=\\\\\"width:100%;background:linear-gradient(135deg,#8e44ad,#9b59b6);color:white;border:none;border-radius:14px;padding:14px;font-size:15px;font-weight:900;cursor:pointer;font-family:inherit;\\\\\">\\ud83d\\udcbe \\u062d\\u0641\\u0638 \\u0627\\u0644\\u062a\\u0641\\u0636\\u064a\\u0644\\u0627\\u062a</button>\"\n            + \"</div></div></div>\";\n        document.body.insertAdjacentHTML(\"beforeend\", html);\n    };\n\n    window._toggleNotif = function(key, el) {\n        const cur = el.getAttribute(\"data-on\") === \"1\";\n        const next = !cur;\n        el.setAttribute(\"data-on\", next ? \"1\" : \"0\");\n        const sw = el.querySelector(\"._notifSwitch\");\n        if (sw) {\n            sw.textContent = next ? \"ON\" : \"OFF\";\n            sw.style.background = next ? \"#e8f5e9\" : \"#ecf0f1\";\n            sw.style.color = next ? \"#2e7d32\" : \"#95a5a6\";\n        }\n    };\n\n    // ═══ Auth Listener ═══"""
cnt = src.count(marker)
print("expected=1, found=" + str(cnt))
if cnt != 1:
    print("STOP")
    sys.exit(1)
src = src.replace(marker, new_block, 1)
tmp = Path("js/customer-app.tmp_check.js")
tmp.write_text(src, encoding="utf-8")
r = subprocess.run(["node", "--check", str(tmp)], capture_output=True, text=True)
tmp.unlink()
if r.returncode != 0:
    print("SYNTAX ERROR:")
    print(r.stderr)
    sys.exit(1)
print("node --check OK")
p.write_text(src, encoding="utf-8")
print("Saved: " + str(old_lines) + " -> " + str(len(src.split(chr(10)))))
